<?php
require __DIR__.'/../app/bootstrap.php';require __DIR__.'/../app/admin_shell.php';require_admin();$db=database();if($_SERVER['REQUEST_METHOD']==='POST'&&verify_csrf('activities',$_POST['csrf']??null)){try{activity_create($db,trim($_POST['admin_name']??''),trim($_POST['public_title']??''),trim($_POST['slug']??''));header('Location: /admin/',true,303);exit;}catch(Throwable $e){$error=$e->getMessage();}}$state=admin_activity_resolution($db);admin_shell_start('activities','Atividades',$state);
?><section class="activities-layout"><section class="admin-panel"><p class="admin-kicker">Novo site</p><h2>Criar atividade</h2><?php if(isset($error)):?><p class="admin-error" role="alert"><?=h($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token('activities'))?>"><label class="admin-field">Nome administrativo<input name="admin_name" required></label><label class="admin-field">Título público<input name="public_title" required></label><label class="admin-field">Slug<input name="slug" required></label><button class="admin-button">Criar atividade</button></form></section><section><p class="admin-kicker">Sites existentes</p><div class="activity-list"><?php if(!$state['activities']):?><div class="admin-empty compact"><h2>Nenhuma atividade criada</h2><p>Crie a primeira atividade para começar a editar o site.</p></div><?php endif;foreach($state['activities'] as $item):?><article class="activity-card"><h2><?=h($item['admin_name'])?></h2><p><?=h(admin_public_activity_url($item))?></p><a href="/admin/?activity=<?=(int)$item['id']?>">Abrir administração</a></article><?php endforeach;?></div></section></section><?php admin_shell_end();
